class _TariqAppState extends State<TariqApp> with WidgetsBindingObserver {
  final tariq=PhoneController();
  SipPhoneController? sipPhone;
  bool useSip=false;
  PhoneController get phone=>useSip?sipPhone!:tariq;
  Future<void> restore() async {
    try {if(await SipPhoneController.storage.read(key:'phone_mode')=='sip'){sipPhone=SipPhoneController();await sipPhone!.initialize();if(mounted)setState(()=>useSip=true);return;}}catch(_){}
    await tariq.initialize();
  }
