  @override void didChangeAppLifecycleState(AppLifecycleState state){if(state==AppLifecycleState.paused&&phone.call==null&&phone.state['online']==true)unawaited(phone.offline());}
  @override void dispose(){WidgetsBinding.instance.removeObserver(this);tariq.dispose();sipPhone?.dispose();super.dispose();}
